
    #[test]
    fn child_complete_group_source_candidate_whole_retirement_revokes_direct_grant(){
        use semio_framework_value::{NativeEncodeControl,ErasedSnapshotRetirement,list::PagedList,retirement::allocation_return::{ParentAllocationReturn,AllocationReturnStep}};
        use semio_framework_os_kernel::os_pack::codec::PackEncodeOptions;
        let f:serde_json::Value=serde_json::from_str(include_str!("@CHILD_RETIREMENT_GRANT_FIXTURE@")).unwrap();assert_eq!(f["sourceBytes"],8194);assert_eq!(f["maximumAllocationBytes"],65536);assert_eq!(f["maximumItems"],1);assert_eq!(f["maximumBytes"],4096);
        for mode in f["modes"].as_array().unwrap(){let mode=mode.as_str().unwrap();let options=PackEncodeOptions::default();let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let mut owner=paged_owner::PagedChildOwner::empty();for(field,text)in[(reader::ChildGroupText::Owner,"owner"),(reader::ChildGroupText::Slot,"slot"),(reader::ChildGroupText::ChildId,"child"),(reader::ChildGroupText::Schema,"child.empty")]{owner.read_metadata_from_encoding_source(field,&text,&options,&mut control).unwrap();}let mut receipt=owner.produce_owned_operation(8194,&options,&mut control,|_,output,control|{output.write_bytes(b"17",control)?;for _ in 0..8192{output.write_bytes(b" ",control)?;}Ok(())}).unwrap();receipt.read_first_schema_from_source(&"label.set-label",&mut control).unwrap();for terminology in semio_framework_ui_locale::Terminology::ALL{for locale in semio_framework_ui_locale::Locale::ALL{receipt.read_label_from_source(terminology,locale,&"label",&mut control).unwrap();}}receipt.commit(&mut control).unwrap();let mut parent=ParentAllocationReturn::<1>::try_new(4096,65536).unwrap();let pointer=owner.operations[0].byte_ref(0).map(|byte|byte as *const u8).unwrap();let original=owner.allocated_bytes();for authority in f["zeroAuthorities"].as_array().unwrap(){let items=authority[0].as_u64().unwrap()as usize;let bytes=authority[1].as_u64().unwrap()as usize;assert_eq!(owner.close_step(items,bytes).unwrap(),semio_framework_value::SnapshotRetirementStep::Pending{released_items:0,released_bytes:0});assert!(!owner.return_one(&mut parent,items,bytes).unwrap().progressed);assert_eq!(owner.allocated_bytes(),original);assert_eq!(owner.view().unwrap().operations.source_at(0).unwrap().len(),8194);assert_eq!(owner.operations[0].byte_ref(0).map(|byte|byte as *const u8),Some(pointer));}
            for _ in 0..64{let step=owner.return_committed_scaffold_one(&mut parent,1).unwrap();assert_eq!(step.returned_allocation_bytes,0);assert!(parent.terminal_is_empty());assert_eq!(owner.view().unwrap().operations.source_at(0).unwrap().len(),8194);assert_eq!(owner.operations[0].byte_ref(0).map(|byte|byte as *const u8),Some(pointer));if !step.progressed{break;}}let allocated=owner.allocated_bytes();let mut released=0;let mut returned=0;if mode=="close"{match owner.close_step(1,4096).unwrap(){semio_framework_value::SnapshotRetirementStep::Pending{released_items,released_bytes}=>{assert_eq!(released_items,1);assert!(released_bytes<=4096);released+=released_bytes;},_=>panic!("full original8194 vanished in its first whole close")}}else{let step=owner.return_one(&mut parent,1,4096).unwrap();assert!(step.progressed);returned+=step.returned_allocation_bytes;}assert_eq!(owner.operations[0].byte_ref(0).map(|byte|byte as *const u8),Some(pointer));assert!(owner.view().is_err(),"direct complete child grant survived first whole retirement");let before=owner.allocated_bytes();assert!(owner.read_metadata_from_encoding_source(reader::ChildGroupText::Owner,&"new-owner",&options,&mut control).is_err());assert!(owner.produce_owned_operation(8194,&options,&mut control,|_,_,_|Ok(())).is_err());assert_eq!(owner.allocated_bytes(),before);
            let mut groups=PagedList::<paged_owner::PagedChildOwner,{isize::MAX as usize}>::empty();while !groups.has_reserved_slot(){let required=groups.next_allocation_bytes().unwrap();control.charge(required).unwrap();let step=groups.reserve_one(4096).unwrap();assert!(step.progressed);assert_eq!(step.allocated_bytes,required);}assert!(groups.push_reserved(owner).is_ok());assert!(paged_encoder::PagedChildGroups::group(&groups,0).is_none(),"outer group facade bypassed direct retirement grant");let owner=groups.get_mut(0).unwrap();for _ in 0..8450{if owner.terminal_is_empty(){break}if mode=="close"{match owner.close_step(1,4096).unwrap(){semio_framework_value::SnapshotRetirementStep::Pending{released_items,released_bytes}=>{assert!(released_items<=1&&released_bytes<=4096);released+=released_bytes;},semio_framework_value::SnapshotRetirementStep::Complete=>break,_=>panic!("original owner refused physical authority")}}else{if !parent.terminal_is_empty(){let required=parent.next_close_byte_demand();assert!(required<=4096);match parent.close_step(1,4096){AllocationReturnStep::Pending{released_items,released_bytes}=>{assert_eq!(released_items,1);assert_eq!(released_bytes,required);released+=released_bytes;},_=>panic!("real parent lost retained token")}}let step=owner.return_one(&mut parent,1,4096).unwrap();assert!(step.progressed);returned+=step.returned_allocation_bytes;}}while !parent.terminal_is_empty(){let required=parent.next_close_byte_demand();match parent.close_step(1,4096){AllocationReturnStep::Pending{released_items,released_bytes}=>{assert_eq!(released_items,1);assert_eq!(released_bytes,required);released+=released_bytes;},_=>panic!("real parent lost final token")}}assert!(owner.terminal_is_empty());assert_eq!(released,allocated);assert_eq!(returned,if mode=="close"{0}else{allocated});groups.pop();while !groups.terminal_is_empty(){let step=groups.release_empty_page(4096).unwrap();assert!(step.progressed);assert!(step.released_allocation_bytes<=4096);}assert!(parent.terminal_is_empty());
        }eprintln!("[DEBUG] direct full8194 child grant survives zero item/byte and committed-schema scaffold return; first whole close/parent-return revokes both direct and paged outer facades before new production, preserving original pointer until explicit1/4096 physical retirement; no production family credit");
    }
